let timer=null,remaining=300,end=0;function clock(){let t=timer?Math.max(0,Math.ceil((end-Date.now())/1000)):remaining;$('#break-clock').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;if(timer&&t===0){clearInterval(timer);timer=null;remaining=0;$('#break-start').textContent='휴식 완료';}}$('#break-start').onclick=()=>{if(timer){remaining=Math.max(0,Math.ceil((end-Date.now())/1000));clearInterval(timer);timer=null;$('#break-start').textContent='계속';}else{if(!remaining)remaining=300;end=Date.now()+remaining*1000;timer=setInterval(clock,250);$('#break-start').textContent='일시정지';}clock();};$('#break-reset').onclick=()=>{clearInterval(timer);timer=null;remaining=300;$('#break-start').textContent='타이머 시작';clock();};
