function xor(){const a=+$('#xor-a').checked,b=+$('#xor-b').checked;$('#xor-board').innerHTML=[[0,0],[0,1],[1,0],[1,1]].map(([x,y])=>`<div class="xor-point ${x===a&&y===b?'chosen':''}"><span>A ${x} · B ${y}</span><strong>${x^y?'켜짐 · 1':'꺼짐 · 0'}</strong></div>`).join('');$('#xor-result').textContent=$('#xor-hidden').checked?`OR: ${a|b} / AND: ${a&b} → ${a|b} AND NOT(${a&b}) = ${a^b}`:`현재 출력 ${a^b} · ${a===b?'두 입력이 같습니다.':'두 입력이 다릅니다.'}`;}['#xor-a','#xor-b','#xor-hidden'].forEach(s=>$(s).onchange=xor);xor();
const trainPoints=[[.06,.2],[.22,.42],[.42,.31],[.64,.69],[.84,.61],[.96,.84]],testPoints=[[.12,.28],[.32,.39],[.53,.54],[.74,.66],[.91,.77]];
function fitPredict(x,mode){if(mode==='constant')return trainPoints.reduce((s,p)=>s+p[1],0)/trainPoints.length;if(mode==='memorize')return trainPoints.reduce((sum,[xi,yi],i)=>sum+yi*trainPoints.reduce((p,[xj],j)=>i===j?p:p*(x-xj)/(xi-xj),1),0);const mx=trainPoints.reduce((s,p)=>s+p[0],0)/6,my=trainPoints.reduce((s,p)=>s+p[1],0)/6;let num=0,den=0;trainPoints.forEach(([a,b])=>{num+=(a-mx)*(b-my);den+=(a-mx)**2;});return my+num/den*(x-mx);}
function fitting(){const mode=$('#fit-mode').value,test=$('#fit-test').checked;let out='<defs><clipPath id="fit-clip"><rect x="30" y="15" width="450" height="205"/></clipPath></defs><path d="M30 15V220H480" fill="none" stroke="#18384c55"/>';const pt=(x,y)=>`${30+x*450},${220-y*200}`;out+='<g clip-path="url(#fit-clip)"><polyline fill="none" stroke="#997349" stroke-width="2" points="'+Array.from({length:101},(_,i)=>pt(i/100,fitPredict(i/100,mode))).join(' ')+'"/>';trainPoints.forEach(([x,y])=>out+=`<circle cx="${30+x*450}" cy="${220-y*200}" r="5" fill="#256783"/>`);if(test)testPoints.forEach(([x,y])=>out+=`<path d="M${30+x*450} ${215-y*200}l5 5-5 5-5-5Z" fill="#ac7126"/>`);out+='</g><text x="35" y="248" fill="#526675" font-size="13">● 훈련 예시　◆ 숨겨둔 시험 예시</text>';$('#fit-plot').innerHTML=out;const mse=data=>data.reduce((s,[x,y])=>s+(fitPredict(x,mode)-y)**2,0)/data.length;$('#fit-result').textContent=`훈련 오차 ${mse(trainPoints).toFixed(4)}${test?' · 시험 오차 '+mse(testPoints).toFixed(4):' · 시험 오차는 아직 숨겨져 있습니다.'}`;}$('#fit-mode').onchange=fitting;$('#fit-test').onchange=fitting;fitting();
function dataShare(){let d=+$('#day-share').value;$('#day-out').textContent=d+'%';$('#data-result').textContent=`전체 정확도 ${(d*.95+(100-d)*.45).toFixed(1)}% · 밤 사진 정확도는 여전히 45%`;}$('#day-share').oninput=dataShare;dataShare();
function rewardMix(){const v=+$('#reward-mix').value;$('#reward-out').textContent=v+'%';const items=[['자극적인 제목의 짧은 영상',95,20],['친절한 수학 개념 설명',55,95],['과학 실험 브이로그',75,70]].map(([name,click,learn])=>({name,click,learn,score:(click*(100-v)+learn*v)/100})).sort((a,b)=>b.score-a.score);$('#reward-ranking').innerHTML=items.map((it,i)=>`<div class="rank-item"><b>${i+1}</b><div>${it.name}<br><small>클릭 ${it.click} · 학습 ${it.learn}</small></div><span>${it.score.toFixed(1)}</span></div>`).join('');}$('#reward-mix').oninput=rewardMix;rewardMix();
